      "The employee may claim unpaid wages through the Ministry of Labor or the Magistrates Court",
      "The employee may terminate the contract if the employer delays payment for more than two consecutive months",
      "The law prohibits deducting any amounts from wages without the workers written consent",
      "Wage disputes are heard before the Magistrates Court as urgent matters",
