    summary_ar:
      "قانون العمل الأردن يلزم صاحب العمل بدفع الرواتب في مواعيدها المحددة. في حال التأخر في الدفع، يحق للموظف المطالبة بالرواتب المستحقة عبر وزارة العمل أو المحكمة الابتدائية، ويمكنه إنهاء العقد إذا تأخر الدفع أكثر من شهرين متتاليين.",
    summary_en:
      "Jordanian labor law requires employers to pay salaries on time. In case of delayed payment, the employee may claim unpaid wages through the Ministry of Labor or the Magistrates Court, and may terminate the contract if payment is delayed for more than two consecutive months.",
    explanation_ar:
      "وجب على صاحب العمل وفقاً لقانون العمل رقم 8 لسنة 1996 دفع أجر العامل في الموعد المحدد في عقد العمل، وإذا لم يُحدد موعد يُدفع الأجر في نهاية كل شهر. إذا تأخر صاحب العمل في الدفع، يحق للموظف تقديم شكوى لوزارة العمل التي تقوم بتحري وفض النزاع خلال 14 يوماً. إذا لم يُحل النزاع، يحق للموظف رفع دعوى أمام المحكمة الابتدائية. وفقاً للمادة 26 من القانون، يحق للعامل إنهاء عقد العمل إذا تأخر صاحب العمل في دفع أجره لمدة شهرين أو أكثر من شهرين متتاليين، مع احتفاظه بكامل مكافأة نهاية الخدمة والتعويض. يُمنع خصم أي مبالغ من الرواتب دون موافقة كتابية من العامل وفقاً للمادة 23.",
    explanation_en:
      "Under Jordanian Labor Law No. 8/1996, the employer must pay the workers wages on the date specified in the employment contract, or at the end of each month if no date is specified. If the employer delays payment, the employee may file a complaint with the Ministry of Labor which investigates and attempts to resolve the dispute within 14 days. If unresolved, the employee may file a lawsuit at the Magistrates Court. Under Article 26, the worker may terminate the contract if the employer delays wages for two or more consecutive months, while retaining full end-of-service gratuity and compensation rights. Deductions from wages without the workers written consent are prohibited under Article 23.",
    when_to_act_ar:
      "عند تأخر صاحب العمل عن دفع راتب واحد يجب اتخاذ إجراء فوري. لا تنتظر أكثر من شهر واحد قبل تقديم شكوى.",
    when_to_act_en:
      "Take immediate action when the employer delays payment of even one salary. Do not wait more than one month before filing a complaint.",
