      "في حال عدم الاستجابة، قدّم شكوى رسمية لوزارة العمل الأردنية",
      "إذا لم يُحل النزاع خلال 14 يوماً، ارفع دعوى أمام المحكمة الابتدائية",
      "احضر الجلسة مع عقد العمل وكشوف الرواتب وأي إثباتات أخرى",
