    summary_en:
      "Divorce in Jordan is governed by the Personal Status Law No. 36 of 2017. Three types are available: consensual divorce, judicial divorce for legitimate cause, and khula (wife-initiated divorce). The court determines the financial and custody rights of each party.",
    explanation_ar:
      "ينظم الطلاق في الأردن قانون الأحوال الشخصية رقم 36 لسنة 2017 الذي يوفر ثلاثة مسارات قانونية. الطلاق بالتراضي (المادة 106): يتم عندما يتفق الزوجان على الطلاق ويُصدق أمام المحكمة المختصة مع تحديد حقوق كل طرف. الطلاق القضائي (المادة 110): يحق للزوجة طلب الطلاق إذا ثبت أحد أسبابه القانونية كـ الإيلاء أو الخُلع أو الإضرار أو غياب الزوج أو عدم الإنفاق. تطليق بالخلع (المادة 113): يحق للزوجة المطالبة بالطلاق أمام المحكمة مع رد المهر و / أو التعويض. تحديد الحقوق المالية تشمل: المهر المتبقي، العدة، النفقة، السكن، ونفقة الأطفال. تتولى المحكمة تحديد جميع الحقوق وفقاً للقانون وأحكام العقد النكاحي.",
    explanation_en:
      "Divorce in Jordan is governed by the Personal Status Law No. 36 of 2017 which provides three legal pathways. Consensual divorce (Article 106): when both parties agree to divorce, it is ratified by the competent court with determination of each partys rights. Judicial divorce (Article 110): the wife may request divorce if one of the statutory grounds is proven such as harm, desertion, or failure to provide maintenance. Khula (Article 113): the wife may petition the court for divorce by returning the dower and/or compensation. Financial rights include: remaining dower, iddah maintenance, housing, and child support. The court determines all rights under the law and the marriage contract terms.",
