    explanation_ar:
      "ينظم تحصيل الديون في الأردن قانون التنفيذ رقم 25 لسنة 2017. وفقاً لهذا القانون، يجب على الدائن الحصول على حكم قضائي بحق المدين قبل بدء أي إجراءات تنفيذ. بعد صدور الحكم، يحق للدائن تقديم طلب التنفيذ أمام مكتب التنفيذ المختص. يحق لمكتب التنفيذ حجز أموال المدين المنقولة (حسابات بنكية، سيارات، بضائع) و/أو عقاراته، وبيعها في مزاد علني لسداد الدين. إذا رفض المدين التكشّف عن أمواله، يمكن للتنفيذ إصدار أمر إلزامه بالكشف. إذا ثبت أن المدين عاجز عن السداد، يمكن للدائن طلب إفلاسه وفقاً لإجراءات الإفلاس المتخصصة. تقادم الديون 15 سنة وفقاً للمادة 320 من القانون المدني.",
