    explanation_ar:
      "يخضع التعويض عن حوادث السيارات في الأردن لأحكام المسؤولية التقصيرية في القانون المدني الأردني رقم 36 لسنة 1976. وفقاً للمادة 256 من القانون، يُعتبر كل من أحدث ضرراً بالغير مسؤولاً عن تعويضه. تشمل أضرار الحادث: الأضرار المادية كتكلفة إصلاح السيارة وتكلفة النقل البديل، والأضرار الجسدية كتكاليف العلاج وفقدان الدخل، والأضرار المعنوية كالألم والمعاناة. تُحدد نسبة المسؤولية وفقاً لنسبة الإخلال من كل طرف. إذا كان هناك تأمين شامل، يمكن للمتضرر المطالبة بالتعويض من شركة التأمين مباشرة. يجب على المتضرر توثيق الحادث بتقرير الشرطة والتقارير الطبية وتقدير الأضرار لدعم مطالبه بالتعويض.",
