    summary_en:
      "The Magistrates Court single judge in Jordan handles small financial disputes under the Civil Procedure Law No. 24 of 1988. Its procedures are simpler and faster, with broader jurisdiction over small and medium financial disputes.",
    explanation_ar:
      "تنظر المحكمة الابتدائية (محكمة منفردة) في الأردن في جميع الدعاوى المالية التي لا تتجاوز قيمتها الحد المحدد وفقاً لقانون أصول المحاكمات المدنية رقم 24 لسنة 1988. وفقاً للمادة 39 من القانون، يحدد الحد الأقصى للدعوى التي تنظرها المحكمة الابتدائية. تتميز المحكمة الابتدائية بأن إجراأتها أبسط وأسرع من المحاكم البدئية، حيث لا تشترط توكيل المحاماة الإلزامي في بعض الحالات البسيطة. تُحسم الدعاوى في جلسة واحدة أو جلسات قليلة، ويُصدر القاضي المنفرد حكمه بعد سماع الأطراف والأدلة. يمكن الاستئناف أمام محكمة الاستئناف خلال 30 يوماً من تاريخ النطق بالحكم.",
    explanation_en:
      "The Magistrates Court single judge in Jordan hears all financial claims that do not exceed the threshold set under the Civil Procedure Law No. 24 of 1988. Under Article 39, the maximum claim value that the Magistrates Court can handle is specified. The Magistrates Court is characterized by simpler and faster procedures than the Courts of First Instance, as mandatory legal representation is not required in some simple cases. Cases are typically resolved in one or few hearings, and the single judge issues judgment after hearing the parties and evidence. Appeal to the Court of Appeal is possible within 30 days of the judgment date.",
