      "احتفظ بنسخة من العقد عندك بشكل دائم",
      "في حال عدم وجود عقد مكتوب، قم بتوثيق علاقة العمل بكشوف الرواتب وشهادة العمل",
      "إذا خالف صاحب العمل شروط العقد أو القانون، قم بتقديم شكوى لوزارة العمل",
      "استشر محامياً حول حقوقك إذا كان هناك تعقيد قانوني",
