    summary_en:
      "Travel bans in Jordan are imposed under the Execution Law No. 25 of 2017 to ensure execution of court judgments. Bans may be lifted by paying the debt, providing a guarantee, or obtaining a court order.",
    explanation_ar:
      "يُفرض حظر السفر في الأردن وفقاً لقانون التنفيذ رقم 25 لسنة 2017 وقانون أصول المحاكمات المدنية رقم 24 لسنة 1988. يحق لمكتب التنفيذ أو المحكمة فرض حظر السفر على شخص له التزامات مالية أو قضايا جارية. تشمل الأسباب الشائعة: الديون المستحقة التي صدر بحكم قضائي بها، الدعاوى القضائية الجارية التي تتطلب حضور الشخص، وأوامر المحكمة بمنع السفر. يمكن لمكتب التنفيذ فرض الحظر عند تقديم طلب من الدائن أو المحكمة. لرفع الحظر، يجب إحدىثلاثة خيارات: سداد الدين بالكامل، أو تقديم كفالة مالية كافية، أو الحصول على حكم قضائي برفع الحظر. يمكن التحقق من وجود حظر سفر عبر البوابة الإلكترونية للحكومة الأردنية.",
    explanation_en:
      "Travel bans in Jordan are imposed under the Execution Law No. 25/2017 and the Civil Procedure Law No. 24/1988. The Execution Office or the court may impose a travel ban on persons with financial obligations or pending cases. Common grounds include: debts subject to court judgments, pending lawsuits requiring the persons appearance, and court orders prohibiting travel. The ban may be imposed upon request from a creditor or the court. To lift the ban, one of three options is required: full payment of the debt, provision of sufficient financial guarantee, or obtaining a court order lifting the ban. Travel ban status can be verified through the Jordanian government electronic portal.",
    when_to_act_ar: "عند اكتشاف وجود حظر سفر، تواصل مع المحكمة أو مكتب التنفيذ فوراً لمعرفة التفاصيل.",
