    summary_en:
      "Bankruptcy in Jordan is governed by the Execution Law No. 25 of 2017. Debtors unable to pay may file for personal or business bankruptcy, and the court may approve a restructuring plan instead of full bankruptcy.",
    explanation_ar:
      "يخضع الإفلاس في الأردن لقانون التنفيذ رقم 25 لسنة 2017. يمكن للمدين سواء كان شخصاً طبيعياً أو اعتبارياً طلب الإفلاس إذا ثبت أنه غير قادر على سداد ديونه المستحقة. تُحال الأصول إلى أمين يُعيّنه القاضي لبيعها وسداد الدائنين وفقاً لأولوياتهم القانونية. يمكن للمحكمة بدلاً من الإفلاس الكامل الموافقة على خطة إعادة هيكلة الديون تشمل: تقسيط الديون على فترات أطول، خفض جزئي من المبالغ المستحقة، أو تأجيل الدفعات. يُسجّل الإفلاس في السجل التجاري ويؤثر على الحالة الائتمانية للمدين.",
    explanation_en:
      "Bankruptcy in Jordan is governed by the Execution Law No. 25/2017. Natural or legal person debtors may file for bankruptcy if proven unable to pay due debts. Assets are transferred to a court-appointed trustee for sale and creditor repayment by legal priority. Instead of full bankruptcy, the court may approve a debt restructuring plan بما في ذلك: installment payments over longer periods, partial reduction of due amounts, or payment deferrals. Bankruptcy is registered in the commercial register and affects the debtors credit status.",
    when_to_act_ar: "عند عدم القدرة على سداد الديون المستحقة، تقدم بطلب الإفلاس أو إعادة الهيكلة قبل صدور أحكام قضائية.",
