    explanation_en:
      "Consumer protection in Jordan is governed by the Consumer Protection Law No. 25/2010 which grants consumers broad rights. Under the law, consumers have the right to: know the true characteristics of goods, receive adequate and accurate information, and freely choose products. If a defective product is purchased, consumers may claim repair, replacement, or refund. Quality responsibility falls on the manufacturer, distributor, and seller consecutively. Complaints may be filed with the Consumer Protection Department which investigates and imposes penalties on violators.",
