    summary_ar:
      "عقد الزواج في الأردن يخضع لقانون الأحوال الشخصية رقم 36 لسنة 2017. يمكن للمحكمة إلزام الزوج بشروط العقد النكاحي من مهر ونفقة وسكن، ويمكن فرض غرامات تأخيرية على المتأخر في التنفيذ.",
    summary_en:
      "Marriage contracts in Jordan are governed by the Personal Status Law No. 36 of 2017. The court may order the husband to comply with marriage contract terms بما في ذلك dower, maintenance, and housing, with delay penalties for non-compliance.",
    explanation_ar:
      "يخضع عقد الزواج في الأردن لقانون الأحوال الشخصية رقم 36 لسنة 2017. وفقاً للقانون، يُعدّ عقد الزواج إتفاقاً ملزمًا للطرفين يتضمن شروطاً مالية وersonal. تشمل الشروط المالية: المهر المدفوع والمتأجل، النفقة الشهرية، السكن، وأي شروط إضافية اتفق عليها الطرفان. إذا أخل الزوج بشروط العقد النكاحي، يمكن للمرأة تقديم طلب أمام محكمة الأحوال الشخصية لإلزام الزوج بالتنفيذ. يمكن للمحكمة فرض غرامات تأخيرية والحكم بخصم المبالغ المستحقة من راتب الزوج عبر مكتب التنفيذ. لا يمكن تعديل الشروط المالية إلا بموافقة الطرفين وتوثيق المحكمة.",
    explanation_en:
      "Marriage contracts in Jordan are governed by the Personal Status Law No. 36/2017. Under the law, the marriage contract is a binding agreement between the parties بما في ذلك financial and personal terms. Financial terms include: paid and deferred dower, monthly maintenance, housing, and any additional agreed conditions. If the husband breaches the marriage contract terms, the wife may petition the Personal Status Court for enforcement. The court may impose delay penalties and order deduction of due amounts from the husbands salary through the Execution Office. Financial terms may only be modified with both parties consent and court notarization.",
