export function getTopics(): Topic[] {
  return topics;
}

export function getTopicBySlug(slug: string): Topic | undefined {
  return topics.find((t) => t.slug === slug);
}

export function getTopicsByArea(area: PracticeArea): Topic[] {
  return topics.filter((t) => t.practice_area === area);
}

export function searchTopics(query: string, locale: Locale): Topic[] {
  const q = query.toLowerCase();
  return topics.filter((t) => {
    if (locale === "ar") {
      return (
        t.title_ar.toLowerCase().includes(q) ||
        t.summary_ar.toLowerCase().includes(q) ||
        t.explanation_ar.toLowerCase().includes(q) ||
        t.user_questions_ar.some((faq) => faq.toLowerCase().includes(q)) ||
        t.key_facts_ar.some((f) => f.toLowerCase().includes(q))
      );
    }
    return (
      t.title_en.toLowerCase().includes(q) ||
      t.summary_en.toLowerCase().includes(q) ||
      t.explanation_en.toLowerCase().includes(q) ||
      t.user_questions_en.some((faq) => faq.toLowerCase().includes(q)) ||
      t.key_facts_en.some((f) => f.toLowerCase().includes(q))
    );
  });
}
